28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (a '+' followed by 8 to 15 digits)")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    @Email
54	    private String email;
55	
56	    @Column(name = "registration_date")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "customer_code")
60	    private String customerCode;
61	
62	    @Column(name = "household_id")
63	    private String householdId;
64	
65	    @Column(name = "namesake_count")
66	    private Integer namesakeCount;
67	
68	    /**
69	     * The current number of owners that belong to this owner's household (owners sharing the same
70	     * {@code householdId}, including this one). Not persisted: it is populated from the current data
71	     * whenever the owner is loaded or saved.
72	     */
73	    @Transient
74	    private Integer householdMemberCount;
75	
76	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
77	    private Set<Pet> pets;
78	
79	    public String getAddress() {
80	        return this.address;
81	    }
82	
83	    public void setAddress(String address) {
84	        this.address = address;
85	    }
86	
87	    public String getCity() {
88	        return this.city;
89	    }
90	
91	    public void setCity(String city) {
92	        this.city = city;
93	    }
94	
95	    public String getTelephone() {
96	        return this.telephone;
97	    }
98	
99	    public void setTelephone(String telephone) {
100	        this.telephone = telephone;
101	    }
102	
103	    public String getEmail() {
104	        return this.email;
105	    }
106	
107	    public void setEmail(String email) {
108	        this.email = email;
109	    }
110	
111	    public LocalDate getRegistrationDate() {
112	        return this.registrationDate;
113	    }
114	
115	    public void setRegistrationDate(LocalDate registrationDate) {
116	        this.registrationDate = registrationDate;
117	    }
118	
119	    public String getCustomerCode() {
120	        return this.customerCode;
121	    }
122	
123	    public void setCustomerCode(String customerCode) {
124	        this.customerCode = customerCode;
125	    }
126	
127	    public String getHouseholdId() {
128	        return this.householdId;
129	    }
130	
131	    public void setHouseholdId(String householdId) {
132	        this.householdId = householdId;
133	    }
134	
135	    public Integer getNamesakeCount() {
136	        return this.namesakeCount;
137	    }
138	
139	    public void setNamesakeCount(Integer namesakeCount) {
140	        this.namesakeCount = namesakeCount;
141	    }
142	
143	    public Integer getHouseholdMemberCount() {
144	        return this.householdMemberCount;
145	    }
146	
147	    public void setHouseholdMemberCount(Integer householdMemberCount) {
148	        this.householdMemberCount = householdMemberCount;
149	    }
150	
151	    /**
152	     * Stamp the owner's registration date with the server's current date on first
153	     * persist when none was supplied, so the default applies on every create path.
154	     */
155	    @PrePersist
156	    protected void onCreate() {
157	        if (this.registrationDate == null) {
158	            this.registrationDate = LocalDate.now();
159	        }
160	    }
161	
162	    protected Set<Pet> getPetsInternal() {
163	        if (this.pets == null) {
164	            this.pets = new HashSet<>();
165	        }
166	        return this.pets;
167	    }
168	
169	    protected void setPetsInternal(Set<Pet> pets) {
170	        this.pets = pets;
171	    }
172	
173	    public List<Pet> getPets() {
174	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
175	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
176	        return Collections.unmodifiableList(sortedPets);
177	    }
178	
179	    public void setPets(List<Pet> pets) {
180	        this.pets = new HashSet<>(pets);
181	    }
182	
183	    public void addPet(Pet pet) {
184	        getPetsInternal().add(pet);
185	        pet.setOwner(this);
186	    }
187	
188	    /**
189	     * Return the Pet with the given name, or null if none found for this Owner.
190	     *
191	     * @param name to test
192	     * @return true if pet name is already in use
193	     */
194	    public Pet getPet(String name) {
195	        return getPet(name, false);
196	    }
197	
198	    /**
199	     * Return the Pet with the given name, or null if none found for this Owner.
200	     *
201	     * @param name to test
202	     * @return true if pet name is already in use
203	     */
204	    public Pet getPet(String name, boolean ignoreNew) {
205	        name = name.toLowerCase();
206	        for (Pet pet : getPetsInternal()) {
207	            if (!ignoreNew || !pet.isNew()) {
208	                String compName = pet.getName();
209	                compName = compName.toLowerCase();
210	                if (compName.equals(name)) {
211	                    return pet;
212	                }
213	            }
214	        }
215	        return null;
216	    }
217	
218	    public Pet getPet(Integer petId) {
219	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
220	    }
221	
222	    @Override
223	    public String toString() {
224	        return new ToStringCreator(this)
225	
226	            .append("id", this.getId())
227	            .append("new", this.isNew())
228	            .append("lastName", this.getLastName())
229	            .append("firstName", this.getFirstName())
230	            .append("address", this.address)
231	            .append("city", this.city)
232	            .append("telephone", this.telephone)
233	            .toString();
234	    }
235	}
