44	/**
45	 * Mostly used as a facade for all Petclinic controllers
46	 * Also a placeholder for @Transactional and @Cacheable annotations
47	 *
48	 * @author Michael Isvy
49	 * @author Vitaliy Fedoriv
50	 */
51	@Service
52	public class ClinicServiceImpl implements ClinicService {
53	
54	    /** Maximum number of owners allowed per city. */
55	    private static final long CITY_CAPACITY = 50L;
56	
57	    /** Maximum number of owners that may be created on a single day (by registration date). */
58	    private static final long DAILY_CAPACITY = 100L;
59	
60	    /** Above this many owners created today, reads carry a bulk-signup warning. */
61	    private static final long BULK_SIGNUP_THRESHOLD = 80L;
62	
63	    private final PetRepository petRepository;
64	    private final VetRepository vetRepository;
65	    private final OwnerRepository ownerRepository;
66	    private final VisitRepository visitRepository;
67	    private final SpecialtyRepository specialtyRepository;
68	    private final PetTypeRepository petTypeRepository;
69	
70	    public ClinicServiceImpl(
71	        PetRepository petRepository,
72	        VetRepository vetRepository,
73	        OwnerRepository ownerRepository,
74	        VisitRepository visitRepository,
75	        SpecialtyRepository specialtyRepository,
76	        PetTypeRepository petTypeRepository) {
77	        this.petRepository = petRepository;
78	        this.vetRepository = vetRepository;
79	        this.ownerRepository = ownerRepository;
80	        this.visitRepository = visitRepository;
81	        this.specialtyRepository = specialtyRepository;
82	        this.petTypeRepository = petTypeRepository;
83	    }
84	
85	    @Override
86	    @Transactional(readOnly = true)
87	    public Collection<Pet> findAllPets() throws DataAccessException {
88	        return petRepository.findAll();
89	    }
90	
91	    @Override
92	    @Transactional(readOnly = true)
93	    public Page<Pet> findPets(Pageable pageable) throws DataAccessException {
94	        return petRepository.findAll(pageable);
95	    }
96	
97	    @Override
98	    @Transactional
99	    public void deletePet(Pet pet) throws DataAccessException {
100	        petRepository.delete(pet);
101	    }
102	
103	    @Override
104	    @Transactional(readOnly = true)
105	    public Visit findVisitById(int visitId) throws DataAccessException {
106	        return findEntityById(() -> visitRepository.findById(visitId));
107	    }
108	
109	    @Override
110	    @Transactional(readOnly = true)
111	    public Collection<Visit> findAllVisits() throws DataAccessException {
112	        return visitRepository.findAll();
113	    }
114	
115	    @Override
116	    @Transactional
117	    public void deleteVisit(Visit visit) throws DataAccessException {
118	        visitRepository.delete(visit);
119	    }
120	
121	    @Override
122	    @Transactional(readOnly = true)
123	    public Vet findVetById(int id) throws DataAccessException {
124	        return findEntityById(() -> vetRepository.findById(id));
125	    }
126	
127	    @Override
128	    @Transactional(readOnly = true)
129	    public Collection<Vet> findAllVets() throws DataAccessException {
130	        return vetRepository.findAll();
131	    }
132	
133	    @Override
134	    @Transactional
135	    public void saveVet(Vet vet) throws DataAccessException {
136	        vetRepository.save(vet);
137	    }
138	
139	    @Override
140	    @Transactional
141	    public void deleteVet(Vet vet) throws DataAccessException {
142	        vetRepository.delete(vet);
143	    }
144	
145	    @Override
146	    @Transactional(readOnly = true)
147	    public Collection<Owner> findAllOwners() throws DataAccessException {
148	        Collection<Owner> owners = ownerRepository.findAll();
149	        return decorateWithHouseholdMemberCount(owners, owners);
150	    }
151	
152	    @Override
153	    @Transactional(readOnly = true)
154	    public Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException {
155	        Page<Owner> owners = (lastName != null)
156	            ? ownerRepository.findByLastName(lastName, pageable)
157	            : ownerRepository.findAll(pageable);
158	        return decorateWithHouseholdMemberCount(owners, owners.getContent());
159	    }
160	
161	    @Override
162	    @Transactional
163	    public void deleteOwner(Owner owner) throws DataAccessException {
164	        ownerRepository.delete(owner);
165	    }
166	
167	    @Override
168	    @Transactional(readOnly = true)
169	    public PetType findPetTypeById(int petTypeId) {
170	        return findEntityById(() -> petTypeRepository.findById(petTypeId));
171	    }
172	
173	    @Override
174	    @Transactional(readOnly = true)
175	    public Collection<PetType> findAllPetTypes() throws DataAccessException {
176	        return petTypeRepository.findAll();
177	    }
178	
179	    @Override
180	    @Transactional
181	    public void savePetType(PetType petType) throws DataAccessException {
182	        petTypeRepository.save(petType);
183	    }
184	
185	    @Override
186	    @Transactional
187	    public void deletePetType(PetType petType) throws DataAccessException {
188	        petTypeRepository.delete(petType);
189	    }
190	
191	    @Override
192	    @Transactional(readOnly = true)
193	    public Specialty findSpecialtyById(int specialtyId) {
194	        return findEntityById(() -> specialtyRepository.findById(specialtyId));
195	    }
196	
197	    @Override
198	    @Transactional(readOnly = true)
199	    public Collection<Specialty> findAllSpecialties() throws DataAccessException {
200	        return specialtyRepository.findAll();
201	    }
202	
203	    @Override
204	    @Transactional
205	    public void saveSpecialty(Specialty specialty) throws DataAccessException {
206	        specialtyRepository.save(specialty);
207	    }
208	
209	    @Override
210	    @Transactional
211	    public void deleteSpecialty(Specialty specialty) throws DataAccessException {
212	        specialtyRepository.delete(specialty);
213	    }
214	
215	    @Override
216	    @Transactional(readOnly = true)
217	    public Collection<PetType> findPetTypes() throws DataAccessException {
218	        return petRepository.findPetTypes();
219	    }
220	
221	    @Override
222	    @Transactional(readOnly = true)
223	    public Owner findOwnerById(int id) throws DataAccessException {
224	        return decorateWithHouseholdMemberCount(findEntityById(() -> ownerRepository.findById(id)));
225	    }
226	
227	    @Override
228	    @Transactional(readOnly = true)
229	    public Pet findPetById(int id) throws DataAccessException {
230	        return findEntityById(() -> petRepository.findById(id));
231	    }
232	
233	    @Override
234	    @Transactional
235	    public void savePet(Pet pet) throws DataAccessException {
236	        pet.setType(findPetTypeById(pet.getType().getId()));
237	        petRepository.save(pet);
238	    }
239	
240	    @Override
241	    @Transactional
242	    public void saveVisit(Visit visit) throws DataAccessException {
243	        visitRepository.save(visit);
244	
245	    }
246	
247	    @Override
248	    @Transactional(readOnly = true)
249	    public Collection<Vet> findVets() throws DataAccessException {
250	        return vetRepository.findAll();
251	    }
252	
253	    @Override
254	    @Transactional
255	    public void saveOwner(Owner owner) throws DataAccessException {
256	        if (owner.isNew()) {
257	            LocalDate effectiveDate = owner.getRegistrationDate() != null
258	                ? owner.getRegistrationDate()
259	                : LocalDate.now();
260	            owner.setRegistrationDate(toBusinessDay(effectiveDate));
261	            if (owner.getCustomerCode() == null) {
262	                owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
263	            }
264	            if (owner.getNamesakeCount() == null) {
265	                owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
266	            }
267	        }
268	        ownerRepository.save(owner);
269	        decorateWithHouseholdMemberCount(owner);
270	    }
271	
272	    /**
273	     * Count the existing owners (before this create) that share the given first and last name,
274	     * compared case-insensitively, as required by the read-only {@code namesakeCount} field.
275	     */
276	    private int countNamesakes(String firstName, String lastName) {
277	        if (firstName == null || lastName == null) {
278	            return 0;
279	        }
280	        return (int) ownerRepository.findAll().stream()
281	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
282	                && lastName.equalsIgnoreCase(owner.getLastName()))
283	            .count();
284	    }
285	
286	    /**
287	     * Build a customer code formatted {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3}
288	     * is the upper-cased first three letters of the owner's city, {@code LAST3} the
289	     * upper-cased first three letters of the owner's last name and {@code NNNN} a per-city,
290	     * 4-digit zero-padded sequence equal to one more than the current number of owners
291	     * already in that city (e.g. {@code 'LON-SMI-0007'}).
292	     */
293	    private String generateCustomerCode(String city, String lastName) {
294	        String cityName = city == null ? "" : city;
295	        String city3 = cityName.substring(0, Math.min(3, cityName.length())).toUpperCase();
296	        String name = lastName == null ? "" : lastName;
297	        String last3 = name.substring(0, Math.min(3, name.length())).toUpperCase();
298	        long sequence = countOwnersInCity(cityName) + 1L;
299	        return String.format("%s-%s-%04d", city3, last3, sequence);
300	    }
301	
302	    /**
303	     * Count the existing owners whose city matches the given city, compared case-insensitively,
304	     * used to derive the per-city sequence of the customer code.
305	     */
306	    private long countOwnersInCity(String city) {
307	        if (city == null) {
308	            return 0L;
309	        }
310	        return ownerRepository.findAll().stream()
311	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
312	            .count();
313	    }
314	
315	    @Override
316	    @Transactional(readOnly = true)
317	    public boolean isCityAtCapacity(String city) throws DataAccessException {
318	        return countOwnersInCity(city) >= CITY_CAPACITY;
319	    }
320	
321	    @Override
322	    @Transactional(readOnly = true)
323	    public boolean isDailyRegistrationAtCapacity() throws DataAccessException {
324	        return countRegisteredToday() >= DAILY_CAPACITY;
325	    }
326	
327	    @Override
328	    @Transactional(readOnly = true)
329	    public boolean isBulkSignupDay() throws DataAccessException {
330	        return countRegisteredToday() > BULK_SIGNUP_THRESHOLD;
331	    }
332	
333	    /**
334	     * Count the owners whose registration date equals today's business day, used by the
335	     * daily create-limit and bulk-signup rules.
336	     */
337	    private long countRegisteredToday() {
338	        LocalDate businessDay = toBusinessDay(LocalDate.now());
339	        return ownerRepository.findAll().stream()
340	            .filter(owner -> businessDay.equals(owner.getRegistrationDate()))
341	            .count();
342	    }
343	
344	    /**
345	     * Rolls a registration date forward onto a business day: a Saturday or Sunday is advanced
346	     * to the following Monday, while a weekday is returned unchanged. Applied to the effective
347	     * registration date (whether supplied or defaulted to the server date) so that the stored
348	     * {@code registrationDate}, every value derived from it (such as the membership number's year
349	     * segment) and the per-day create-limit all use the adjusted business day.
350	     */
351	    private static LocalDate toBusinessDay(LocalDate date) {
352	        DayOfWeek day = date.getDayOfWeek();
353	        if (day == DayOfWeek.SATURDAY) {
354	            return date.plusDays(2);
355	        }
356	        if (day == DayOfWeek.SUNDAY) {
357	            return date.plusDays(1);
358	        }
359	        return date;
360	    }
361	
362	    @Override
363	    @Transactional(readOnly = true)
364	    public boolean isTelephoneInUse(String telephone) throws DataAccessException {
365	        String normalized = normalizeTelephone(telephone);
366	        if (normalized == null) {
367	            return false;
368	        }
369	        return ownerRepository.findAll().stream()
370	            .map(owner -> normalizeTelephone(owner.getTelephone()))
371	            .anyMatch(normalized::equals);
372	    }
373	
374	    @Override
375	    @Transactional(readOnly = true)
376	    public boolean isEmailInUse(String email) throws DataAccessException {
377	        String normalized = normalizeEmail(email);
378	        if (normalized == null) {
379	            return false;
380	        }
381	        return ownerRepository.findAll().stream()
382	            .map(owner -> normalizeEmail(owner.getEmail()))
383	            .anyMatch(normalized::equals);
384	    }
385	
386	    private static String normalizeEmail(String email) {
387	        return email == null ? null : email.toLowerCase(Locale.ROOT);
388	    }
389	
390	    @Override
391	    @Transactional(readOnly = true)
392	    public boolean isHouseholdInUse(String lastName, String address) throws DataAccessException {
393	        String normalizedLastName = normalizeHouseholdValue(lastName);
394	        String normalizedAddress = normalizeHouseholdAddress(address);
395	        if (normalizedLastName.isEmpty() || normalizedAddress.isEmpty()) {
396	            return false;
397	        }
398	        return ownerRepository.findAll().stream()
399	            .anyMatch(owner -> normalizedLastName.equals(normalizeHouseholdValue(owner.getLastName()))
400	                && normalizedAddress.equals(normalizeHouseholdAddress(owner.getAddress())));
401	    }
402	
403	    @Override
404	    @Transactional(readOnly = true)
405	    public String householdIdFor(String lastName, String address) throws DataAccessException {
406	        String key = normalizeHouseholdValue(lastName) + "\u0000" + normalizeHouseholdAddress(address);
407	        try {
408	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
409	            StringBuilder sb = new StringBuilder(32);
410	            for (int i = 0; i < 8; i++) {
411	                sb.append(String.format("%02X", digest[i]));
412	            }
413	            return sb.toString();
414	        } catch (NoSuchAlgorithmException ex) {
415	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
416	        }
417	    }
418	
419	    /**
420	     * Normalizes a household field (last name or address) for duplicate comparison by trimming,
421	     * collapsing runs of whitespace to a single space and lower-casing, so differently cased or
422	     * spaced but equivalent values compare equal.
423	     */
424	    private static String normalizeHouseholdValue(String value) {
425	        if (value == null) {
426	            return "";
427	        }
428	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
429	    }
430	
431	    /**
432	     * Normalizes an address for household comparison by first applying the canonical address
433	     * normalization (trim, collapse whitespace, upper-case and expand common abbreviations) and
434	     * then the shared household-value normalization, so every address comparison uses the same
435	     * normalized form regardless of how the value was originally supplied.
436	     */
437	    private static String normalizeHouseholdAddress(String address) {
438	        return normalizeHouseholdValue(AddressNormalizer.normalize(address));
439	    }
440	
441	    /**
442	     * Populate each given owner's transient {@code householdMemberCount} with the current number of
443	     * owners that share its {@code householdId}. Owners without a household id are left at a count
444	     * of zero.
445	     *
446	     * <p>The household sizes are computed in a single pass over the owner table regardless of how
447	     * many owners are being decorated, so decorating a whole page does not re-scan per element.
448	     */
449	    private <T> T decorateWithHouseholdMemberCount(T result, Collection<Owner> owners) {
450	        if (!owners.isEmpty()) {
451	            Map<String, Long> sizeByHousehold = ownerRepository.findAll().stream()
452	                .filter(owner -> owner.getHouseholdId() != null)
453	                .collect(Collectors.groupingBy(Owner::getHouseholdId, Collectors.counting()));
454	            for (Owner owner : owners) {
455	                long size = owner.getHouseholdId() == null
456	                    ? 0L
457	                    : sizeByHousehold.getOrDefault(owner.getHouseholdId(), 0L);
458	                owner.setHouseholdMemberCount((int) size);
459	            }
460	        }
461	        return result;
462	    }
463	
464	    /**
465	     * Decorate a single (possibly {@code null}) owner with its household member count and return it.
466	     */
467	    private Owner decorateWithHouseholdMemberCount(Owner owner) {
468	        return decorateWithHouseholdMemberCount(owner, owner == null ? List.of() : List.of(owner));
469	    }
470	
471	    /**
472	     * Reduces a telephone number to its canonical E.164 form so that differently formatted but
473	     * equivalent numbers compare equal. A value already stored that cannot form valid E.164
474	     * (e.g. unusual legacy data) falls back to its digits-only form rather than failing lookup.
475	     */
476	    private static String normalizeTelephone(String telephone) {
477	        if (telephone == null) {
478	            return null;
479	        }
480	        try {
481	            return TelephoneNormalizer.toE164(telephone);
482	        } catch (InvalidTelephoneException ex) {
483	            return telephone.replaceAll("\\D", "");
484	        }
485	    }
486	
487	    @Override
488	    @Transactional(readOnly = true)
489	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
490	        Collection<Owner> owners = ownerRepository.findByLastName(lastName);
491	        return decorateWithHouseholdMemberCount(owners, owners);
492	    }
493	
494	    @Override
495	    @Transactional(readOnly = true)
496	    public Collection<Visit> findVisitsByPetId(int petId) {
497	        return visitRepository.findByPetId(petId);
498	    }
499	
500	    @Override
501	    @Transactional(readOnly = true)
502	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
503	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
504	    }
