31	
32	/**
33	 * Mostly used as a facade so all controllers have a single point of entry
34	 *
35	 * @author Michael Isvy
36	 * @author Vitaliy Fedoriv
37	 */
38	public interface ClinicService {
39	
40		Pet findPetById(int id) throws DataAccessException;
41		Collection<Pet> findAllPets() throws DataAccessException;
42	    Page<Pet> findPets(Pageable pageable) throws DataAccessException;
43		void savePet(Pet pet) throws DataAccessException;
44		void deletePet(Pet pet) throws DataAccessException;
45	
46		Collection<Visit> findVisitsByPetId(int petId);
47		Visit findVisitById(int visitId) throws DataAccessException;
48		Collection<Visit> findAllVisits() throws DataAccessException;
49		void saveVisit(Visit visit) throws DataAccessException;
50		void deleteVisit(Visit visit) throws DataAccessException;
51		Vet findVetById(int id) throws DataAccessException;
52		Collection<Vet> findVets() throws DataAccessException;
53		Collection<Vet> findAllVets() throws DataAccessException;
54		void saveVet(Vet vet) throws DataAccessException;
55		void deleteVet(Vet vet) throws DataAccessException;
56		Owner findOwnerById(int id) throws DataAccessException;
57		Collection<Owner> findAllOwners() throws DataAccessException;
58		Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException;
59		void saveOwner(Owner owner) throws DataAccessException;
60		void deleteOwner(Owner owner) throws DataAccessException;
61	
62		/**
63		 * Returns {@code true} if any owner already uses the given telephone number. The argument and every
64		 * stored value are compared in their normalized (digits-only) form, so differently formatted but
65		 * equivalent numbers collide. Enforces the "unique telephone" invariant for every owner write path.
66		 *
67		 * @param telephone the telephone number to look for (in any format)
68		 * @return whether the normalized telephone is already in use by an owner
69		 */
70		boolean isTelephoneInUse(String telephone) throws DataAccessException;
71	
72		/**
73		 * Returns {@code true} if any owner already uses the given email address. The argument and every
74		 * stored value are compared in their lower-cased form, so differently cased but equivalent
75		 * addresses collide. Enforces the "unique email" invariant on owner creation.
76		 *
77		 * @param email the email address to look for (in any casing)
78		 * @return whether the lower-cased email is already in use by an owner
79		 */
80		boolean isEmailInUse(String email) throws DataAccessException;
81	
82		/**
83		 * Returns {@code true} if another owner already has both the given last name and address. The
84		 * last name and address are compared case-insensitively with runs of whitespace collapsed to a
85		 * single space (and surrounding whitespace trimmed), so differently cased or spaced but
86		 * equivalent values collide. Enforces the "one household per last name + address" invariant on
87		 * owner creation.
88		 *
89		 * @param lastName the last name to look for
90		 * @param address the address to look for
91		 * @return whether an existing owner shares the same normalized last name and address
92		 */
93		boolean isHouseholdInUse(String lastName, String address) throws DataAccessException;
94	
95		/**
96		 * Returns a stable, shared household identifier derived from the given last name and address.
97		 * The inputs are normalized the same way as {@link #isHouseholdInUse(String, String)}
98		 * (trimmed, runs of whitespace collapsed, lower-cased) before hashing, so every owner in the
99		 * same household (same last name + address) deterministically receives the identical value.
100		 *
101		 * @param lastName the last name of the household
102		 * @param address the address of the household
103		 * @return a stable identifier shared by all owners of the household
104		 */
105		String householdIdFor(String lastName, String address) throws DataAccessException;
106	
107		/**
108		 * Returns {@code true} if the given city has already reached its owner capacity, i.e. it already
109		 * contains 50 or more owners (compared case-insensitively, the same way the per-city customer-code
110		 * sequence counts them). Enforces the "at most 50 owners per city" invariant on owner creation.
111		 *
